142	function filesUnder(root: string): string[] {
143	  const found: string[] = [];
144	  const walk = (dir: string) => {
145	    for (const entry of readdirSync(dir).sort()) {
146	      const path = `${dir}/${entry}`;
147	      if (statSync(path).isDirectory()) walk(path);
148	      else found.push(path);
